var t=`0983-seolleongtang`;var i=`world-0983`;var s=`KR`;var a=`east-asia`;var o=4;var g=268;var r={en:`Seolleongtang`,ua:`Соллонтхан`};var l={en:`Seolleongtang is a South Korea dish made with beef bones, beef brisket, glass noodles, green onion. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Соллонтхан, страва кухні країни Південна Корея. Основні складники: яловичі кістки, яловича грудинка, скляна локшина, зелена цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 240 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 240 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:240,i:[[`beef-bones`,1600,`g`],[`water`,3e3,`ml`],[`beef-brisket`,400,`g`]]},{en:`Shred or tear the cooked components, then fold together with the listed additions.`,ua:`Нашаткуйте або розберіть готові компоненти на волокна й змішайте з зазначеними додатками.`,t:[`shredding`,`mixing`],m:12,i:[]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 12 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 12 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:12,i:[[`glass-noodles`,250,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`green-onion`,100,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,3,`g`]]}];var m={slug:t,id:i,country:`KR`,region:a,servings:4,minutes:268,title:r,text:l,steps:d};export{s as country,m as default,i as id,g as minutes,a as region,o as servings,t as slug,d as steps,l as text,r as title};